184	    // §1.2 post-injection protection. DRAM = secded (Huawei DDR ECC). Acts on
185	    // the mutated `data` byte BY REFERENCE before write-back, so an undo
186	    // restores the original byte (== golden). popcount(mask) = bits flipped.
187	    //   none   -> Raw (leave = escape). Default, zero regression.
188	    //   secded -> 1-bit: undo the mutation (Corrected); 2-bit: poison-log +
189	    //             leave (Latent — AbstractMemory backing store has no poison
190	    //             bit, E3 proxy); >=3: SilentEscape.
191	    CHAOSMem::ProtectionOutcome
192	    CHAOSMem::applyProtection(uint8_t &data, uint8_t mask,
193	                              uint8_t orig_byte, FaultType ft)
194	    {
195	        int bits = __builtin_popcount(mask);
196	        ProtectionOutcome outcome = ProtectionOutcome::Raw;
197	
198	        if (protection_model == "none") {
199	            outcome = ProtectionOutcome::Raw;  // leave = escape (default)
200	        } else if (protection_model == "secded") {
201	            if (bits == 1) {
202	                // 1-bit: undo (restore the original byte before write-back).
203	                data = orig_byte;
204	                outcome = ProtectionOutcome::Corrected;
205	            } else if (bits == 2) {
206	                // 2-bit: poison-log + leave (Latent). No poison bit in the
207	                // backing store -> E3 proxy; the corruption propagates as SDC
208	                // if read, but we LOG what real-hw DDR SECDED would contain.
209	                outcome = ProtectionOutcome::Latent;
210	            } else {
211	                outcome = ProtectionOutcome::SilentEscape;  // >=3-bit silent
212	            }
213	        } else {
214	            outcome = ProtectionOutcome::Raw;  // unknown model -> raw
215	        }
216	        (void)ft;
217	
218	        if (write_log) {
219	            *(log_stream->stream()) << "    protection: model=" << protection_model
220	                << " bits=" << bits << " -> " << protectionOutcomeToString(outcome)
221	                << std::endl;
222	        }
223	        return outcome;
224	    }
